# Compute all e_n for n=1..32
e = {}
for n in range(1, 33):
    s = sum(mobius(n//d) * 2**d for d in divisors(n))
    e[n] = s // n

# Build p(x) = product (1 - x^n)^{e[n]} mod x^33
# Use polynomial multiplication mod x^33
N = 33
coeffs = [0]*N
coeffs[0] = 1  # start with 1

for n in range(1, 33):
    # Multiply by (1 - x^n)^{e[n]}
    # (1 - x^n)^{e[n]} = sum_{j=0}^{e[n]} C(e[n],j) * (-1)^j * x^{n*j}
    # But e[n] can be huge, so we compute binomials
    from math import comb
    factor_coeffs = {}
    for j in range(0, e[n]+1):
        if n*j >= N:
            break
        c = comb(e[n], j) * ((-1)**j)
        factor_coeffs[n*j] = c

    new_coeffs = [0]*N
    for i in range(N):
        if coeffs[i] == 0:
            continue
        for power, fc in factor_coeffs.items():
            if i + power < N:
                new_coeffs[i+power] += coeffs[i] * fc
    coeffs = new_coeffs

print('Coefficients of p(x):')
for i in range(N):
    print(f'  x^{i}: {coeffs[i]}')
